// src/hooks/useTelegramWebApp.ts
import { useEffect, useState } from 'react';
import type { TelegramWebApp } from '../telegram';

// Reads the host bridge once. Outside Telegram this is null and callers
// fall back to plain in-page controls.
export function useTelegramWebApp(): TelegramWebApp | null {
  const [webApp] = useState<TelegramWebApp | null>(() => window.Telegram?.WebApp ?? null);

  useEffect(() => {
    if (!webApp) return;
    webApp.ready();
    webApp.expand();
  }, [webApp]);

  return webApp;
}
