// src/hooks/useBackButton.ts
import { useEffect } from 'react';
import type { TelegramWebApp } from '../telegram';

// Routes Telegram's BackButton to the screen's own history instead of
// drawing a second back arrow on the page.
export function useBackButton(webApp: TelegramWebApp | null, onBack: () => void, visible = true): void {
  useEffect(() => {
    if (!webApp) return;
    if (!visible) {
      webApp.BackButton.hide();
      return;
    }
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [webApp, onBack, visible]);
}
