// src/hooks/useMainButton.ts
import { useEffect } from 'react';
import type { TelegramWebApp } from '../telegram';

interface MainButtonOptions {
  text: string;
  onClick: () => void;
  disabled?: boolean;
  loading?: boolean;
}

// Puts the screen's one primary action in Telegram's bottom bar button
// instead of a page-drawn sticky footer button.
export function useMainButton(
  webApp: TelegramWebApp | null,
  { text, onClick, disabled, loading }: MainButtonOptions
): void {
  useEffect(() => {
    if (!webApp) return;
    const { MainButton } = webApp;
    MainButton.setText(text);
    MainButton.show();
    MainButton.onClick(onClick);
    return () => {
      MainButton.offClick(onClick);
    };
  }, [webApp, text, onClick]);

  useEffect(() => {
    if (!webApp) return;
    const { MainButton } = webApp;
    if (loading) {
      MainButton.showProgress(false);
      return;
    }
    MainButton.hideProgress();
    disabled ? MainButton.disable() : MainButton.enable();
  }, [webApp, disabled, loading]);

  useEffect(() => {
    return () => {
      webApp?.MainButton.hide();
    };
  }, [webApp]);
}
