```tsx
// src/components/CheckoutScreen.tsx
import React, { useCallback, useId, useMemo, useState } from 'react';
import { useTelegramWebApp } from '../hooks/useTelegramWebApp';
import { useBackButton } from '../hooks/useBackButton';
import { useMainButton } from '../hooks/useMainButton';
import type { CartItem, DeliveryAddress, DeliveryAddressErrors } from '../types';
import './CheckoutScreen.css';

interface CheckoutScreenProps {
  cartItems: CartItem[];
  currency?: string;
  deliveryFee?: number;
  onBack: () => void;
  onSubmitOrder: (address: DeliveryAddress) => Promise<void>;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(amount);
}

function validateAddress(address: DeliveryAddress): DeliveryAddressErrors {
  const errors: DeliveryAddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter the recipient\u2019s full name';
  if (!/^\+?[0-9\s()-]{7,}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street address';
  if (!address.postalCode.trim()) errors.postalCode = 'Enter a postal code';
  return errors;
}

export default function CheckoutScreen({
  cartItems,
  currency = 'USD',
  deliveryFee = 0,
  onBack,
  onSubmitOrder,
}: CheckoutScreenProps): React.JSX.Element {
  const webApp = useTelegramWebApp();
  const formId = useId();

  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [hasAttemptedSubmit, setHasAttemptedSubmit] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const total = subtotal + deliveryFee;

  const errors = useMemo(() => validateAddress(address), [address]);
  const isFormValid = Object.keys(errors).length === 0;

  const displayError = (field: keyof DeliveryAddress): string | undefined =>
    touched[field] || hasAttemptedSubmit ? errors[field] : undefined;

  const handleChange = (field: keyof DeliveryAddress) =>
    (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setAddress((prev) => ({ ...prev, [field]: e.target.value }));
      setIsDirty(true);
    };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const handlePay = useCallback(async () => {
    setHasAttemptedSubmit(true);
    const validationErrors = validateAddress(address);
    if (Object.keys(validationErrors).length > 0) {
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }

    setIsSubmitting(true);
    setSubmitError(null);
    try {
      await onSubmitOrder(address);
      webApp?.HapticFeedback.notificationOccurred('success');
      setIsDirty(false);
      webApp?.disableClosingConfirmation();
    } catch (err) {
      webApp?.HapticFeedback.notificationOccurred('error');
      const message = err instanceof Error ? err.message : 'Payment failed. Please try again.';
      setSubmitError(message);
      if (webApp) {
        webApp.showAlert(message);
      } else {
        window.alert(message);
      }
    } finally {
      setIsSubmitting(false);
    }
  }, [address, onSubmitOrder, webApp]);

  const handleBack = useCallback(() => {
    if (isDirty && !isSubmitting) {
      const message = 'Discard delivery details and go back to the cart?';
      if (webApp) {
        webApp.showConfirm(message, (confirmed) => {
          if (confirmed) onBack();
        });
      } else if (window.confirm(message)) {
        onBack();
      }
    } else {
      onBack();
    }
  }, [isDirty, isSubmitting, onBack, webApp]);

  useBackButton(webApp, handleBack, true);
  useMainButton(webApp, {
    text: `Pay ${formatPrice(total, currency)}`,
    onClick: handlePay,
    disabled: !isFormValid,
    loading: isSubmitting,
  });

  React.useEffect(() => {
    if (!webApp) return;
    isDirty ? webApp.enableClosingConfirmation() : webApp.disableClosingConfirmation();
    return () => webApp.disableClosingConfirmation();
  }, [webApp, isDirty]);

  const fields: Array<{
    field: keyof DeliveryAddress;
    label: string;
    type?: string;
    required?: boolean;
    autoComplete?: string;
  }> = [
    { field: 'fullName', label: 'Full name', autoComplete: 'name', required: true },
    { field: 'phone', label: 'Phone number', type: 'tel', autoComplete: 'tel', required: true },
    { field: 'city', label: 'City', autoComplete: 'address-level2', required: true },
    { field: 'street', label: 'Street address', autoComplete: 'address-line1', required: true },
    { field: 'apartment', label: 'Apartment / suite', autoComplete: 'address-line2' },
    { field: 'postalCode', label: 'Postal code', autoComplete: 'postal-code', required: true },
  ];

  return (
    <div className="checkout">
      <h1 className="checkout__title">Checkout</h1>

      <section className="checkout__section" aria-labelledby={`${formId}-cart-heading`}>
        <h2 className="checkout__section-title" id={`${formId}-cart-heading`}>
          Order ({cartItems.length})
        </h2>
        <ul className="cart-list">
          {cartItems.map((item) => (
            <li className="cart-item" key={item.id}>
              <img className="cart-item__image" src={item.imageUrl} alt={item.name} />
              <div className="cart-item__info">
                <span className="cart-item__name">{item.name}</span>
                {item.variant && <span className="cart-item__variant">{item.variant}</span>}
                <span className="cart-item__meta">
                  {item.quantity} \u00d7 {formatPrice(item.price, currency)}
                </span>
              </div>
              <span className="cart-item__price">{formatPrice(item.price * item.quantity, currency)}</span>
            </li>
          ))}
        </ul>
      </section>

      <section className="checkout__section" aria-labelledby={`${formId}-address-heading`}>
        <h2 className="checkout__section-title" id={`${formId}-address-heading`}>
          Delivery address
        </h2>
        <form
          className="address-form"
          onSubmit={(e) => {
            e.preventDefault();
            handlePay();
          }}
        >
          {fields.map(({ field, label, type, required, autoComplete }) => {
            const inputId = `${formId}-${field}`;
            const errorId = `${inputId}-error`;
            const error = displayError(field);
            return (
              <div className="form-field" key={field}>
                <label className="form-field__label" htmlFor={inputId}>
                  {label}
                  {required && <span className="form-field__required"> *</span>}
                </label>
                <input
                  id={inputId}
                  className="form-field__input"
                  type={type ?? 'text'}
                  value={address[field]}
                  onChange={handleChange(field)}
                  onBlur={handleBlur(field)}
                  autoComplete={autoComplete}
                  aria-invalid={Boolean(error)}
                  aria-describedby={error ? errorId : undefined}
                />
                {error && (
                  <span className="form-field__error" id={errorId} role="alert">
                    {error}
                  </span>
                )}
              </div>
            );
          })}

          <div className="form-field">
            <label className="form-field__label" htmlFor={`${formId}-comment`}>
              Delivery notes (optional)
            </label>
            <textarea
              id={`${formId}-comment`}
              className="form-field__input form-field__input--textarea"
              value={address.comment}
              onChange={handleChange('comment')}
              onBlur={handleBlur('comment')}
              rows={3}
            />
          </div>
        </form>
      </section>

      <section className="checkout__section checkout__summary" aria-label="Order summary">
        <div className="summary__row">
          <span>Subtotal</span>
          <span>{formatPrice(subtotal, currency)}</span>
        </div>
        <div className="summary__row">
          <span>Delivery</span>
          <span>{deliveryFee > 0 ? formatPrice(deliveryFee, currency) : 'Free'}</span>
        </div>
        <div className="summary__row summary__row--total">
          <span>Total</span>
          <span>{formatPrice(total, currency)}</span>
        </div>
        {submitError && (
          <p className="checkout__error" role="alert">
            {submitError}
          </p>
        )}
      </section>

      {/* Fallback controls for testing outside Telegram; inside Telegram
          BackButton/MainButton own navigation and the primary action. */}
      {!webApp && (
        <div className="checkout__fallback-bar">
          <button type="button" className="button button--secondary" onClick={handleBack}>
            Back to cart
          </button>
          <button
            type="button"
            className="button button--primary"
            onClick={handlePay}
            disabled={!isFormValid || isSubmitting}
          >
            {isSubmitting ? 'Paying\u2026' : `Pay ${formatPrice(total, currency)}`}
          </button>
        </div>
      )}
    </div>
  );
}
```

