```tsx
// src/App.tsx (example wiring)
import React, { useState } from 'react';
import CheckoutScreen from './components/CheckoutScreen';
import type { CartItem, DeliveryAddress } from './types';

const sampleCart: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', imageUrl: '/img/headphones.jpg', price: 59.99, quantity: 1 },
  { id: '2', name: 'Phone Case', variant: 'Black', imageUrl: '/img/case.jpg', price: 14.5, quantity: 2 },
];

export default function App(): React.JSX.Element {
  const [screen, setScreen] = useState<'cart' | 'checkout'>('checkout');

  if (screen === 'cart') {
    return <div>Cart screen goes here.</div>;
  }

  const handleSubmitOrder = async (address: DeliveryAddress) => {
    const response = await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: sampleCart, address }),
    });
    if (!response.ok) {
      throw new Error('Could not process payment. Please try again.');
    }
  };

  return (
    <CheckoutScreen
      cartItems={sampleCart}
      currency="USD"
      deliveryFee={4.99}
      onBack={() => setScreen('cart')}
      onSubmitOrder={handleSubmitOrder}
    />
  );
}
```

Notes on the platform-specific choices:
- **Back navigation** uses Telegram's `BackButton` only (`useBackButton`), routed to `onBack`; no in-page arrow. If the address form is dirty, it confirms via `showConfirm` before discarding.
- **Pay** is the screen's single primary action, placed in `MainButton` (`useMainButton`), disabled while the address form is invalid, showing the progress spinner during submission — not a second page-drawn button.
- Both hooks render a minimal fallback (plain buttons) only when `window.Telegram.WebApp` is absent, so the component is still usable in a plain browser during development.
- Colors come entirely from `--tg-theme-*` CSS variables (Telegram updates these live on theme change, so no manual re-render wiring is needed), layout height uses `--tg-viewport-stable-height` instead of `100vh`, and padding accounts for both safe-area insets.
- Closing confirmation is toggled on/off based on form dirtiness so a swipe-down won't silently discard entered address data.
- All inputs have visible `<label>`s and 44px-tall touch targets per the Mini App touch-target floor.
